import boto3

def stream_completion(prompt, model_id='amazon.titan-text-express-v1'):
    client = boto3.client('bedrock-runtime')

    response = client.invoke_model(
        modelId=model_id,
        body={
            'prompt': prompt,
            'maxTokens': 500,
            'temperature': 0.5
        }
    )

    response_body = response['body'].read()
    response_json = json.loads(response_body)

    for token in response_json['completion']:
        yield token

import boto3

def answer_with_context(question, context):
    client = boto3.client('bedrock-runtime')
    response = client.invoke_model(
        model_id='amazon.bedrock.model',
        body={
            'prompt': f'{context} Answer the following question: {question}',
            'max_tokens': 150
        }
    )
    result = response['body'].read()
    return result.decode('utf-8')

import boto3

def extract_json(text):
    bedrock = boto3.client('bedrock-runtime')
    model_id = 'amazon.titan-text-express-v1'
    body = {
        'inputText': text,
        'textGenerationConfig': {
            'maxTokenCount': 4096,
            'stopSequences': [],
            'temperature': 0,
            'topP': 0.9
        }
    }
    response = bedrock.invoke_model(
        body=json.dumps(body),
        modelId=model_id,
        accept='application/json',
        contentType='application/json'
    )
    response_body = json.loads(response.get('body').read())
    return response_body.get('results')[0].get('outputText')

if __name__ == '__main__':
    text = 'Example text to extract JSON from.'
    extracted_json = extract_json(text)
    print(extracted_json)

import boto3

def summarize_text(text):
    bedrock_client = boto3.client('bedrock-runtime', region_name='us-east-1')
    model_id = 'amazon.titan-text-express-v1'
    payload = {
        'inputText': text,
        'textSize': {'maxToken': 512}
    }
    response = bedrock_client.invoke_model(
        modelId=model_id,
        body=payload
    )
    result = json.loads(response['body'].read())
    return result['outputText']

if __name__ == '__main__':
    text_to_summarize = 'Long text to be summarized goes here.'
    summary = summarize_text(text_to_summarize)
    print(summary)
